const allHindi = Object.freeze({ ...hindi, ...soilAnalysisHindi, ...simpleSoilTestingHindi, ...intrusionHindi, ...overviewHindi });
const english = Object.freeze(Object.fromEntries(Object.keys(allHindi).map((key) => [key, key])));
export const translations = Object.freeze({ en: english, hi: allHindi });
const englishByHindi = Object.freeze(Object.fromEntries(Object.entries(allHindi).map(([english, translated]) => [translated, english])));

export function normalizeApplicationLanguage(value) { return value === "hi" ? "hi" : "en"; }
export function getVoiceRecognitionLocale(language) { return APPLICATION_LANGUAGES[normalizeApplicationLanguage(language)]; }

function translatePattern(text) {
  const loaded = text.match(/^(\d+) of (\d+) discussions loaded\.$/);
  if (loaded) return `${loaded[2]} में से ${loaded[1]} चर्चाएँ लोड हुईं।`;
  const comments = text.match(/^(\d+) comments?$/);
  if (comments) return `${comments[1]} टिप्पणियाँ`;
  return null;
}

export function translateUiText(text, language = DEFAULT_APPLICATION_LANGUAGE) {
  if (typeof text !== "string") return text;
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  const core = text.trim();
  if (normalizeApplicationLanguage(language) === "en") {
    return englishByHindi[core] ? `${leading}${englishByHindi[core]}${trailing}` : text;
  }
  const translated = translations.hi[core] || translatePattern(core);
  return translated ? `${leading}${translated}${trailing}` : text;
}

export function getMissingHindiTranslationKeys(keys) {
  return keys.filter((key) => typeof translations.hi[key] !== "string" || !translations.hi[key].trim());
}

export function getTranslationIntegrityIssues() {
  return Object.keys(translations.en).filter((key) => typeof translations.hi[key] !== "string" || !translations.hi[key].trim());
}
